import {rotations} from './core.js';
const stages={
 'Maíz':{title:'El campo se llena de maíz',text:'Esta es la primera campaña del ejemplo. Antes de sembrar, confirma que el riego pueda sostenerla.',color:'#e9c85a'},
 'leguminosa':{title:'Ahora cambia el cultivo',text:'Después de la cosecha, entra una leguminosa. Rotar significa cambiar la familia del cultivo en este lote; la especie concreta debe elegirse con un técnico.',color:'#9fd480'},
 'Leguminosa':{title:'Comienza con una leguminosa',text:'Explora esta campaña como una alternativa. Su adaptación depende de la especie, el suelo y el agua reales.',color:'#9fd480'},
 'Yuca':{title:'Una campaña de yuca',text:'Este ejemplo ocupa el lote durante más tiempo. Comprueba suelo, agua y mercado antes de comprometer el terreno.',color:'#74bc9a'},
 'descanso':{title:'Una pausa para revisar el terreno',text:'Se termina la campaña y se revisa el suelo. Descansar no recupera el suelo por sí solo: acuerda cobertura y manejo con tu técnico.',color:'#cbb18a'}};
function plant(x,y,i,kind){const rest=kind==='descanso',corn=kind==='Maíz';return '<g class="rotation-plant" style="--delay:'+i*18+'ms" transform="translate('+x+' '+y+')"><ellipse cy="7" rx="15" ry="6" fill="#0a352b30"/>'+(rest?'<path d="M-12 0l24 4m-20 2 15-9" stroke="#d4bd83" stroke-width="3"/>':'<g class="rotation-stem"><path d="M0 0v-'+(corn?65:36)+'" stroke="#386b43" stroke-width="4"/><path d="M0-15Q-30-42-23-45Q0-43 0-15M0-25Q29-55 25-51Q3-48 0-25" fill="#82b653"/>'+(corn?'<ellipse cx="4" cy="-37" rx="6" ry="14" fill="#f1ca59"/><path d="M0-65l-8-10m8 10 8-10" stroke="#e8d492" stroke-width="3"/>':'<ellipse cx="-10" cy="-36" rx="12" ry="7" fill="#9fd480"/><ellipse cx="10" cy="-42" rx="12" ry="7" fill="#609f52"/>')+'</g>')+'</g>';}
export function mountRotationStage(host,farm){let sequence=['Maíz','leguminosa','descanso'],step=0;
host.innerHTML='<section class="rotation-theatre"><div class="rotation-launch"><button type="button" id="rotation-enter">Explorar mi campo a pantalla completa ↗</button><button type="button" id="rotation-exit" hidden>Salir de la experiencia ✕</button></div><div class="rotation-heading"><small>UN CAMPO. DISTINTAS ETAPAS.</small><h2>Mira cómo cambia<br>tu próxima campaña.</h2><p>Elige un recorrido y toca cada etapa. Los árboles permanecen; el lote anual cambia.</p><label>Elige un camino para tu campo<select id="rotation-choice"><option>Maíz → leguminosa → descanso</option><option>Leguminosa → descanso</option><option>Yuca → descanso</option></select></label></div><div id="rotation-paths" class="rotation-paths"></div><div class="rotation-scene" id="rotation-scene"></div><div class="rotation-story" aria-live="polite"></div><nav class="rotation-timeline" aria-label="Etapas de la rotación"></nav><div class="rotation-actions"><button type="button" id="rotation-prev">← Anterior</button><button type="button" id="rotation-next">Siguiente etapa →</button></div><button type="button" id="rotation-compare">Comparar mis caminos ⇄</button><section id="rotation-comparison" hidden></section><p class="rotation-note">Ilustración educativa de un lote anual separado, no de tu polígono real. No representa rendimientos ni un calendario validado.</p></section>';
const theatre=host.querySelector('.rotation-theatre');let previousOverflow='';
function closeExperience(){if(!theatre.classList.contains('rotation-immersive'))return;theatre.classList.remove('rotation-immersive');document.body.style.overflow=previousOverflow;host.querySelector('#rotation-enter').hidden=false;host.querySelector('#rotation-exit').hidden=true;host.querySelector('#rotation-enter').focus();}
host.querySelector('#rotation-enter').onclick=()=>{previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';theatre.classList.add('rotation-immersive');host.querySelector('#rotation-enter').hidden=true;host.querySelector('#rotation-exit').hidden=false;host.querySelector('#rotation-exit').focus();};
host.querySelector('#rotation-exit').onclick=closeExperience;
theatre.addEventListener('keydown',e=>{if(e.key==='Escape')closeExperience();if(e.key==='Tab'&&theatre.classList.contains('rotation-immersive')){const els=[...theatre.querySelectorAll('button,select')].filter(el=>!el.hidden&&!el.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
host.querySelector('#rotation-compare').onclick=()=>{const panel=host.querySelector('#rotation-comparison');panel.hidden=false;panel.innerHTML='<h3>Tres caminos. Tú decides qué explorar.</h3><p>Estos son ejemplos, no una recomendación validada para tu finca. Las restricciones corresponden al escenario actual.</p><div class="rotation-compare-grid">'+rotations(farm).map(r=>'<article><h4>'+r.name+'</h4><p>💧 Agua: '+['','poca','intermedia','más abundante'][r.water]+'</p><p>📅 '+r.months+' meses en este ejemplo</p><strong>'+(r.reasons.length?'Necesita ajustes':'Encaja en este escenario')+'</strong><p>'+(r.reasons.join(' · ')||'Cumple agua, tiempo y lote. Falta validar suelo, costos y mercado.')+'</p><button type="button" data-play="'+r.name+'">Probar este camino →</button></article>').join('')+'</div><p>Los frutales se conservan. Las rotaciones ocurren en un lote anual separado; sin ese lote son solo ejemplos educativos.</p>';panel.querySelectorAll('[data-play]').forEach(btn=>btn.onclick=()=>{host.querySelector('#rotation-choice').value=btn.dataset.play;sequence=btn.dataset.play.split(' → ');step=0;panel.hidden=true;draw();host.querySelector('#rotation-scene').scrollIntoView({block:'center'});});panel.scrollIntoView({block:'start'});};
function draw(){host.querySelector('#rotation-paths').innerHTML=['Maíz → leguminosa → descanso','Leguminosa → descanso','Yuca → descanso'].map((name,i)=>'<button type="button" data-path="'+name+'" aria-pressed="'+(sequence.join(' → ')===name)+'"><span>'+['🌽','🌱','🌿'][i]+'</span>'+name+'</button>').join('');host.querySelectorAll('[data-path]').forEach(btn=>btn.onclick=()=>{sequence=btn.dataset.path.split(' → ');step=0;host.querySelector('#rotation-choice').value=btn.dataset.path;host.querySelector('#rotation-comparison').hidden=true;draw();});const kind=sequence[step],s=stages[kind];host.querySelector('#rotation-scene').innerHTML='<svg viewBox="0 0 800 390" role="img" aria-label="Lote anual en etapa de '+kind+', junto a frutales que se conservan"><ellipse cx="400" cy="344" rx="330" ry="29" fill="#06251e50"/><circle cx="681" cy="65" r="32" fill="#f1cd77"/><path d="M70 180 390 55 735 186 415 335Z" fill="#b5c982"/><path d="M70 180v33l345 155v-33Z" fill="#98704c"/><path d="M415 335v33l320-149v-33Z" fill="#70583e"/><path d="M105 185 330 95 540 183 315 280Z" fill="#97764d"/>'+[0,1,2,3].map(r=>'<path d="M'+(118+r*45)+' '+(190+r*19)+'l220-88" stroke="#c9ac76" stroke-width="4"/>').join('')+Array.from({length:20},(_,i)=>plant(145+(i%5)*41+Math.floor(i/5)*35,184-(i%5)*16+Math.floor(i/5)*22,i,kind)).join('')+'<path d="M365 90 605 190 420 287" fill="none" stroke="#7fc9c1" stroke-width="12"/>'+[0,1,2].map(i=>'<g transform="translate('+(528+i*57)+' '+(169+i*23)+')"><path d="M0 0v-35" stroke="#745438" stroke-width="7"/><circle cy="-49" r="30" fill="#367a4a"/><circle cx="-13" cy="-57" r="20" fill="#69a354"/><circle cx="9" cy="-37" r="5" fill="#edbf64"/></g>').join('')+'<text x="510" y="300" fill="#143e30" font-size="17" font-weight="700">Frutales: se conservan</text></svg>';
host.querySelector('.rotation-story').innerHTML='<small>ETAPA '+(step+1)+' DE '+sequence.length+'</small><h3>'+s.title+'</h3><p>'+s.text+'</p>';
host.querySelector('.rotation-timeline').innerHTML=sequence.map((v,i)=>'<button type="button" data-step="'+i+'" '+(i===step?'aria-current="step"':'')+'><span>'+(i+1)+'</span>'+v+'</button>').join('');host.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{step=Number(el.dataset.step);draw()});host.querySelector('#rotation-prev').disabled=step===0;host.querySelector('#rotation-next').textContent=step===sequence.length-1?'Comparar todas las alternativas →':'Siguiente etapa →';}
host.querySelector('#rotation-choice').onchange=e=>{sequence=e.target.value.split(' → ');step=0;draw()};host.querySelector('#rotation-prev').onclick=()=>{step=Math.max(0,step-1);draw()};host.querySelector('#rotation-next').onclick=()=>{if(step===sequence.length-1){host.querySelector('#rotation-compare').click();return;}step++;draw()};draw();host.querySelector('#rotation-enter').click();}
